const products=[
{id:'keynade-mx',name:'Keynade MX',en:'12-KEY MECHANICAL FIDGET',type:'press',format:'打印成品',color:'#eee8de',art:'photo',image:'keynade/01-front.jpg',price:499,verified:true,desc:'12 个独立机械按键，把键盘的手感握进掌心。',detail:'手雷造型与机械键轴结合的掌心解压小物。12 个大面板可独立按压，其余小面板为固定造型件。转动握持角度，找到下一个想按的位置。',mark:'01'},
{id:'cloud-key',name:'按键挂饰',en:'TAKE JOY WITH YOU',type:'press',format:'打印成品',color:'#f6dfab',art:'cloud',desc:'把一朵软乎乎的好心情，挂在身边。',detail:'将按键玩法带在身边的挂饰类别。具体产品照片、规格与配件以正式发布为准。',mark:'02'},
{id:'spin-ring',name:'旋转解压小物',en:'ROUND & ROUND',type:'spin',format:'打印成品',color:'#f1c6b5',art:'spin',desc:'手指转一圈，日常多一点轻松。',detail:'围绕手指旋转玩法展开的解压小物类别。具体造型、结构与配件以正式发布为准。',mark:'03'},
{id:'good-file',name:'数字设计文件',en:'MAKE YOUR OWN GOOD',type:'file',format:'数字文件',color:'#cfdfcd',art:'file',desc:'用自己的打印机，让一个好点子成形。',detail:'面向希望自行打印和组装的使用者。商品照片、文件格式、配件及授权范围以正式发布为准。',mark:'04'}];
function assetUrl(path){return (/\/(en|zh-cn)\//.test(location.pathname)?'../assets/':'assets/')+path;}
function priceLabel(p){return p.price?'NT$'+p.price:'NT$ · 售价未公布';}
function art(p){if(p.image)return `<img class="real-product-image" src="${assetUrl(p.image)}" alt="Keynade MX 金色成品正面实拍" loading="lazy" decoding="async">`;if(p.type==='file')return `<span class="photo-slot"><span class="slot-type">虚拟商品</span><strong>数字设计</strong><small>自行打印 · 不含实体产品</small></span>`;return `<span class="photo-slot" aria-hidden="true"></span>`}

const qs=s=>document.querySelector(s);
const makerWorldProfile='https://makerworld.com/zh/@OGStudio';
// Set verified live product URLs here once the store is open.
const saleLinks={};
let filter='all';
function buyAction(p){const url=saleLinks[p.id];if(url&&/^https:\/\/myship\.7-11\.com\.tw\//.test(url))return `<a class="button yellow" href="${url}" target="_blank" rel="noopener noreferrer">前往 7-ELEVEN 賣貨便购买</a>`;return '<span class="sale-status">尚未开售</span>';}
function renderProducts(){if(!qs('#products'))return;qs('#products').innerHTML=products.filter(p=>document.body.dataset.catalog==='digital'?p.type==='file':p.type!=='file'&&(filter==='all'||p.type===filter)).map(p=>`<article class="product-card"><button class="product-art" style="background:${p.color}" data-detail="${p.id}" aria-label="查看${p.name}详情">${art(p)}${p.type==='file'?`<span class="card-stamp">${p.format}</span>`:''}<span class="art-index">OGS / ${p.mark}</span></button><div class="product-info"><div class="product-meta"><span>${p.en}</span><span>${p.verified?'12 KEYS':'商品类别'}</span></div><h3><button class="title-link" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="card-bottom"><span>${priceLabel(p)}</span><button class="text-button card-details" data-detail="${p.id}">查看详情</button></div></div></article>`).join('');}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts();}
function detail(id){const p=products.find(p=>p.id===id);if(!p)return;if(p.type!=='file'){location.href='product.html?id='+encodeURIComponent(id);return;}qs('#product-detail').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en}</span><h2>${p.name}</h2><p>${p.detail}</p><span class="pill">虚拟商品 · 不含实体产品</span><p class="detail-note">设计文档尚未开售，文件内容与授权以正式发布为准。</p><a class="button mint" href="${makerWorldProfile}" target="_blank" rel="noopener noreferrer">我的 MakerWorld 设计主页</a></div></div>`;qs('#product-dialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.detail)detail(b.dataset.detail);if(b.hasAttribute('data-close'))b.closest('dialog').close();});
qs('#open-info').onclick=()=>qs('#info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
qs('#year').textContent=new Date().getFullYear();renderProducts();
const profileSlot=qs('#makerworld-profile');if(profileSlot){const link=document.createElement('a');link.className='button mint';link.href=makerWorldProfile;link.target='_blank';link.rel='noopener noreferrer';link.textContent='我的 MakerWorld 设计主页';profileSlot.append(link);profileSlot.hidden=false;}
const pageLinks={home:'index.html',products:'products.html',designs:'design-files.html',about:'about.html',product:'products.html'};document.querySelectorAll('header nav:not(.language-switch) a,.catalog-nav a').forEach(a=>{if(a.getAttribute('href')===pageLinks[document.body.dataset.page])a.setAttribute('aria-current','page');});
const keynadePhotos=[{file:'keynade/01-front.jpg',label:'正面实拍'},{file:'keynade/02-side.jpg',label:'侧面实拍'},{file:'keynade/03-top-and-pin.jpg',label:'顶部与装饰插销实拍'}];
if(qs('#full-product')){const id=new URLSearchParams(location.search).get('id');const p=products.find(p=>p.id===(id==='good-key'?'keynade-mx':id)&&p.type!=='file');if(!p){qs('#full-product').innerHTML='<h1>没有找到这件商品。</h1><p>请返回实体产品页，重新选择。</p><a class="button yellow" href="products.html">浏览实体产品</a>';}else if(p.id==='keynade-mx'){renderKeynade(p);}else{document.title=p.name+' — One Goods Studio';qs('#full-product').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en} / ${p.type==='press'?'按压派':'旋转派'}</span><h1>${p.name}</h1><span class="pill">实体产品</span><p>${p.detail}</p><p><strong>NT$ · 售价未公布</strong></p>${buyAction(p)}<div class="product-purchase-note"><b>购买渠道：7-ELEVEN 賣貨便</b><p class="detail-note">产品照片、材质、尺寸及售价以正式发布为准。当前尚未开售。</p></div></div></div>`;}}


function renderKeynade(p){document.title='Keynade MX — One Goods Studio';qs('#full-product').innerHTML=`<div class="keynade-intro"><div class="keynade-gallery"><figure><img id="keynade-main-photo" src="${assetUrl(keynadePhotos[0].file)}" alt="Keynade MX · ${keynadePhotos[0].label}"><figcaption id="keynade-caption">${keynadePhotos[0].label}</figcaption></figure><div class="gallery-thumbs" role="group" aria-label="商品实拍视角">${keynadePhotos.map((photo,i)=>`<button data-gallery-index="${i}" aria-label="${photo.label}" aria-pressed="${i===0}"><img src="${assetUrl(photo.file)}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="keynade-summary"><span class="eyebrow">KEYNADE MX / PRESS & RELAX</span><h1>Keynade MX</h1><p class="keynade-subtitle">12 键机械按压手雷</p><p>${p.detail}</p><div class="keynade-facts"><span><b>12</b>独立按键</span><span><b>MX</b>机械键轴结构</span><span><b>1</b>金属珠链随附</span></div><p class="keynade-price">NT$499</p><span class="sale-status">尚未开售</span><p class="detail-note">已组装成品，包含 12 颗已安装轴体与 1 条金属珠链。</p></div></div><section class="keynade-details"><div><span class="eyebrow">THE LITTLE DETAILS</span><h2>让每一次按压，都有手感。</h2><p>几何外壳上的 12 个大面板，都是可独立按压的机械按键。顶部插销可以拔出、插回，是造型与把玩的装饰细节。</p><p>3D 打印的层纹与金色闪点，保留在真实物件的表面。按压声音与手感依搭配的轴体而定。</p></div><div class="keynade-specs"><h2>规格与随附内容</h2><dl><div><dt>品名</dt><dd>Keynade MX</dd></div><div><dt>按键数量</dt><dd>12 个独立机械按键</dd></div><div><dt>轴体结构</dt><dd>MX-Style</dd></div><div><dt>配色</dt><dd>金色闪点，依实拍展示</dd></div><div><dt>成品配置</dt><dd>Keynade MX ×1，已组装并安装 12 颗轴体</dd></div><div><dt>随附配件</dt><dd>金属珠链 ×1</dd></div><div><dt>价格</dt><dd>NT$499 · 尚未开售</dd></div></dl></div></section><section class="keynade-notes"><h2>关于这件小物</h2><p>顶部插销为装饰零件；小面板为固定造型件，12 个大面板可按压。实拍中的场景物件不属于随附内容。</p><p>当前仅展示产品资料，尚未开售。</p></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery-index]');if(!b)return;const photo=keynadePhotos[Number(b.dataset.galleryIndex)];if(!photo)return;qs('#keynade-main-photo').src=assetUrl(photo.file);qs('#keynade-main-photo').alt='Keynade MX · '+photo.label;qs('#keynade-caption').textContent=photo.label;document.querySelectorAll('[data-gallery-index]').forEach(button=>button.setAttribute('aria-pressed',button===b));});
